function normPal(s){return (s||'').toLowerCase().replace(/[^a-z0-9一-龥]/g,'');}
function isPalindrome(s){var n=normPal(s); if(!n.length) return false; return n===n.split('').reverse().join('');}
function longestPalindrome(s){
  var best='', str=(s||'');
  for(var i=0;i<str.length;i++){ for(var j=i+1;j<=str.length;j++){ var sub=str.slice(i,j); if(isPalindrome(sub) && sub.length>best.length) best=sub; } }
  return {sub:best, len:best.length};
}
var EXPORTS={isPalindrome:isPalindrome,longestPalindrome:longestPalindrome,normPal:normPal};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PalindromeForgePure = EXPORTS; }
